-- Photo viewer. Only what differs from swayimg's defaults is here; colors follow the wallpaper:
-- colors.lua next to this file is generated by Quickshell (theme_appliers/swayimg.py).

local ok, c = pcall(dofile, os.getenv("HOME") .. "/.config/swayimg/colors.lua")
if not ok then
  c = {
    background = 0xff0b0b0e, text = 0xffeeeeee, text_background = 0xb30b0b0e, accent = 0xff8a63f0,
    tile = 0xff17171a, tile_selected = 0xff2a2340, checker_a = 0xff1a1a1d, checker_b = 0xff262629,
  }
end

swayimg.decoration = false                 -- niri draws no titlebars, the shell style has none
swayimg.imagelist.adjacent = true          -- opening one photo lists the rest of its folder

-- text overlay: shell font, shown briefly in the corners
swayimg.text.font = "Geist"
swayimg.text.size = 16
swayimg.text.padding = 16
swayimg.text.color = c.text
swayimg.text.background = c.text_background
swayimg.text.shadow = 0x00000000
swayimg.text.timeout = 2

-- viewer
swayimg.viewer.set_window_background(c.background)
swayimg.viewer.set_image_chessboard(16, c.checker_a, c.checker_b)
swayimg.viewer.mark_color = c.accent
swayimg.viewer.text = {
  topleft = { "{name}" },
  topright = { "{list.index} / {list.total}" },
  bottomleft = { "{frame.width}×{frame.height}  ·  {scale}" },
}

-- arrows flip photos like any gallery; the image is moved by dragging instead
swayimg.viewer.on_key("left", function() swayimg.viewer.open("prev") end)
swayimg.viewer.on_key("right", function() swayimg.viewer.open("next") end)
swayimg.viewer.on_key("q", function() swayimg.exit() end)

-- slideshow
swayimg.slideshow.set_window_background(c.background)

-- gallery (Enter switches between it and the viewer)
swayimg.gallery.window_color = c.background
swayimg.gallery.unselected_color = c.tile
swayimg.gallery.selected_color = c.tile_selected
swayimg.gallery.border_color = c.accent
swayimg.gallery.border_size = 2
swayimg.gallery.padding_size = 8
swayimg.gallery.selected_scale = 1.06
swayimg.gallery.thumb_size = 180
swayimg.gallery.pstore = true             -- keep thumbnails on disk, big folders open faster
swayimg.gallery.text = { topright = { "{list.index} / {list.total}" } }
swayimg.gallery.on_key("q", function() swayimg.exit() end)
